 * Given a replica, find where it's replicating from
 *
 * @param Mysql $mysql MySQL connection object
 * @param string $fqdn Fully qualified domain name of the replica
 * @return string The fully qualified domain name of the primary server
 */
function _fetch_primary_fqdn(Mysql $mysql, string $fqdn): string {
    $inst = get_db_instance($mysql, $fqdn);
    $status = $inst->showSlaveStatus();
    $p = $status['Master_Host'] ?? '';
    ensure(!empty($p), wfMessage('replication-master-host-not-found')->inLanguage('en')->text(), $fqdn);
    return $p;
}
