 * @return string|null
 */
function getImageCaption($image): ?string {
    // Check if extended metadata is available
    if ($image['imageinfo'] && $image['imageinfo'][0] && $image['imageinfo'][0]['extmetadata']) {
        $metadata = $image['imageinfo'][0]['extmetadata'];

        // Check if the label exists in the metadata
        if (isset($metadata['Label'])) {
            $caption = $metadata['Label']['value'];
            return stripHtml($caption);
        }
    }

    return null;
}
