public function generateTokens(string $tokenType): array {
    $tokens = [];
    if ($tokenType === 'TSR') {
        // Generate tokens for TSR
        foreach ($this->generateTSRTokens() as $token) {
            $tokens[$token] = true;
        }
    } elseif ($tokenType === 'Other') {
        // Generate tokens for other types
        foreach ($this->generateOtherTokens() as $token) {
            $tokens[$token] = true;
        }
    }
    return $tokens;
}

/**
 * Generates tokens specifically for TSR.
