/**
 * Generator of union of sorted iterables.
 *
 * @param iterable[] $iterables Array of iterables to merge and sort.
 * @return \Generator<int,mixed> A generator yielding elements from all iterables in sorted order.
 */
function unionSortedIterables(array $iterables): \Generator {
    $heap = new SplMinHeap();

    foreach ($iterables as $key => $iterable) {
        if (!is_iterable($iterable)) {
            throw new InvalidArgumentException("All elements must be iterable.");
        }

        foreach ($iterable as $value) {
            $heap->insert([$value, $key]);
        }
    }

    while (!$heap->isEmpty()) {
        yield $heap->extract()[0];
    }
}
