/**
 * Retrieves the structured data label for the file as the caption.
 *
 * @param array $image The image data.
 * @return string|null The caption or null if not available.
 */
public function getImageCaption(array $image): ?string {
    // Check if the image has extended metadata
    if (isset($image['imageinfo'][0]['extmetadata'])) {
        $metadata = $image['imageinfo'][0]['extmetadata'];

        // Check if the structured data label exists
        if (isset($metadata['page.entityterms.label']) && isset($metadata['page.entityterms.label']['value'])) {
            $caption = $metadata['page.entityterms.label']['value'];
            return strip_tags($caption);
        }
    }

    return null;
}
